import ast, subprocess
files = subprocess.check_output(['git','ls-files','sphinx/*.py'], cwd='/testbed', text=True).split()
for f in files:
    if f.endswith('__init__.py') and 'sphinx/__init__' not in f and f.count('/')>1:
        pass
    src = open('/testbed/'+f).read()
    tree = ast.parse(src)
    imported = {}
    for n in ast.walk(tree):
        if isinstance(n, (ast.Import, ast.ImportFrom)):
            for a in n.names:
                name = (a.asname or a.name).split('.')[0]
                if name != '*' and name != 'annotations': imported[name] = n.lineno
    used = set()
    for n in ast.walk(tree):
        if isinstance(n, ast.Name): used.add(n.id)
        elif isinstance(n, ast.Attribute):
            pass
    # names in string annotations / __all__
    for name, ln in imported.items():
        if name in used: continue
        line = src.splitlines()[ln-1]
        if 'NoQA' in line or 'noqa' in line: continue
        # also check text occurrences beyond import (string annotations, casts)
        occ = src.count(name)
        if occ <= 1:
            print(f'{f}:{ln}: {name}')
EOF
cd /testbed && python /tmp/tools/unused.py

